// Current Language & State (English only)
const currentLang = 'en';

function t(key) {
  return p$['en'][key] || key;
}

// ============================================================================
// Content Localization (English)
// ============================================================================
function updatePageLanguage() {
  // Update all elements with data-i18n
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.dataset.i18n;
    const text = t(key);
    if (text) {
      if (el.dataset.i18nHtml === 'true') {
        el.innerHTML = text.replace(/\n/g, '<br/>');
      } else {
        el.textContent = text;
      }
    }
  });

  // Update all placeholders
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.dataset.i18nPlaceholder;
    const text = t(key);
    if (text) {
      el.placeholder = text;
    }
  });

  // Re-render dynamic RSVP guest inputs if present
  renderGuestInputs();
  renderChildrenInputs();
}

// ============================================================================
// Background Music Controller
// ============================================================================
let audio = null;
let isAudioPlaying = false;
let isMuted = false;

function initAudio() {
  if (!audio) {
    audio = new Audio('assests/audio/music_tVoSTrZy.mp3');
    audio.loop = true;
    audio.volume = 0.5;

    audio.addEventListener('play', () => {
      isAudioPlaying = true;
      updateAudioToggleUI();
    });

    audio.addEventListener('pause', () => {
      isAudioPlaying = false;
      updateAudioToggleUI();
    });
  }
}

function startAudio() {
  initAudio();
  if (audio && audio.paused) {
    audio.play().catch(e => console.log('Autoplay deferred:', e));
  }
}

function toggleAudioMute() {
  if (!audio) {
    startAudio();
    return;
  }
  isMuted = !isMuted;
  audio.muted = isMuted;
  updateAudioToggleUI();
}

function updateAudioToggleUI() {
  const toggleBtn = document.getElementById('audio-toggle');
  if (!toggleBtn) return;

  if (isAudioPlaying && !isMuted) {
    toggleBtn.innerHTML = `
      <div class="sound-wave" title="Mute Audio">
        <span></span><span></span><span></span><span></span>
      </div>
    `;
    toggleBtn.setAttribute('aria-label', 'Mute audio');
  } else {
    toggleBtn.innerHTML = `
      <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.7" d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.7" d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" />
      </svg>
    `;
    toggleBtn.setAttribute('aria-label', 'Unmute audio');
  }
}

// ============================================================================
// Interactive Opening Experience (Envelope -> Curtain -> Hero Reveal)
// ============================================================================
function setupIntroExperience() {
  const introOverlay = document.getElementById('intro-overlay');
  const envelopeVideo = document.getElementById('envelope-video');
  const knotVideo = document.getElementById('knot-video');
  const heroText = document.getElementById('hero-invitation-text');
  if (!introOverlay) return;

  // Lock initial body scrolling
  document.body.style.overflow = 'hidden';

  let step = 'idle'; // idle -> envelope -> knot -> fading -> done
  let heroRevealed = false;
  let hasEnded = false;

  function handleUserTap() {
    if (step !== 'idle') return;
    step = 'envelope';

    // Start ambient music
    startAudio();

    // Start envelope video
    if (envelopeVideo) {
      envelopeVideo.style.opacity = '1';
      envelopeVideo.play().catch(() => {});
    }
  }

  introOverlay.addEventListener('click', handleUserTap);

  if (envelopeVideo) {
    envelopeVideo.addEventListener('timeupdate', () => {
      if (step === 'envelope' && envelopeVideo.duration) {
        // Transition to knot video slightly before envelope video ends for seamless handoff
        if (envelopeVideo.duration - envelopeVideo.currentTime <= 0.7) {
          step = 'knot';
          if (knotVideo) {
            knotVideo.style.opacity = '1';
            knotVideo.play().catch(() => {});
          }
        }
      }
    });

    envelopeVideo.addEventListener('ended', () => {
      if (step === 'envelope') {
        step = 'knot';
        if (knotVideo) {
          knotVideo.style.opacity = '1';
          knotVideo.play().catch(() => {});
        }
      }
    });
  }

  if (knotVideo) {
    knotVideo.addEventListener('timeupdate', () => {
      // At ~2 seconds into knot video, fade in Hero text underneath
      if (knotVideo.currentTime >= 2.0 && !heroRevealed) {
        heroRevealed = true;
        if (heroText) {
          heroText.style.opacity = '1';
          heroText.style.transform = 'translateY(0)';
        }
      }

      // 1 second before knot ends, start fading out the intro overlay
      if (!hasEnded && knotVideo.duration && (knotVideo.duration - knotVideo.currentTime <= 1.0)) {
        hasEnded = true;
        completeIntro();
      }
    });

    knotVideo.addEventListener('ended', () => {
      if (!hasEnded) {
        hasEnded = true;
        completeIntro();
      }
    });
  }

  function completeIntro() {
    document.body.style.overflow = '';
    introOverlay.classList.add('fade-out');
    if (heroText) {
      heroText.style.opacity = '1';
      heroText.style.transform = 'translateY(0)';
    }
    setTimeout(() => {
      introOverlay.style.display = 'none';
    }, 1600);
  }
}

// ============================================================================
// Real-time Countdown Timer (Indian Standard Time Asia/Kolkata +05:30)
// ============================================================================
function updateCountdown() {
  const targetIso = '2026-10-22T16:30:00+05:30';
  const targetDate = new Date(targetIso).getTime();
  const now = Date.now();
  const diff = targetDate - now;

  const daysEl = document.getElementById('countdown-days');
  const hoursEl = document.getElementById('countdown-hours');
  const minutesEl = document.getElementById('countdown-minutes');
  const secondsEl = document.getElementById('countdown-seconds');

  if (diff <= 0) {
    if (daysEl) daysEl.textContent = '0';
    if (hoursEl) hoursEl.textContent = '0';
    if (minutesEl) minutesEl.textContent = '0';
    if (secondsEl) secondsEl.textContent = '0';
    return;
  }

  const days = Math.floor(diff / (1000 * 60 * 60 * 24));
  const hours = Math.floor((diff / (1000 * 60 * 60)) % 24);
  const minutes = Math.floor((diff / (1000 * 60)) % 60);
  const seconds = Math.floor((diff / 1000) % 60);

  if (daysEl) daysEl.textContent = days;
  if (hoursEl) hoursEl.textContent = hours;
  if (minutesEl) minutesEl.textContent = minutes;
  if (secondsEl) secondsEl.textContent = seconds;
}

// ============================================================================
// Scroll Parallax on Curtains (DU section)
// ============================================================================
function setupCurtainParallax() {
  const programSection = document.getElementById('program-section');
  const curtainLeft = document.getElementById('curtain-left');
  const curtainRight = document.getElementById('curtain-right');
  if (!programSection || !curtainLeft || !curtainRight) return;

  function onScroll() {
    const rect = programSection.getBoundingClientRect();
    const windowHeight = window.innerHeight;
    const isMobile = window.innerWidth < 768;

    // Smooth scroll interpolation as section moves into view
    const total = windowHeight * 0.6;
    const current = windowHeight - rect.top;
    const progress = Math.min(Math.max(current / total, 0), 1);

    // Frame the section naturally with subtle parallax as it enters the view
    const startOffset = isMobile ? -5 : -3;
    const endOffset = isMobile ? -19 : -10;
    const offset = startOffset + progress * (endOffset - startOffset);

    curtainLeft.style.left = `${offset}%`;
    curtainRight.style.right = `${offset}%`;
  }

  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
}

// ============================================================================
// Scroll Reveal Observer
// ============================================================================
function setupScrollReveal() {
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('is-revealed');
        observer.unobserve(entry.target);
      }
    });
  }, {
    threshold: 0.15,
    rootMargin: '0px 0px -40px 0px'
  });

  document.querySelectorAll('.reveal-on-scroll').forEach(el => {
    observer.observe(el);
  });
}

