function setupRsvpForm() {
  const form = document.getElementById('wedding-rsvp-form');
  if (!form) return;
  const attendanceRadios = document.querySelectorAll('input[name="attendance"]');
  const attendingFields = document.getElementById('attending-fields');
  const declineFields = document.getElementById('decline-fields');

  const guestCountDisplay = document.getElementById('guest-count-display');
  const guestMinusBtn = document.getElementById('guest-minus-btn');
  const guestPlusBtn = document.getElementById('guest-plus-btn');

  const childrenRadios = document.querySelectorAll('input[name="has_children"]');
  const childrenCountWrapper = document.getElementById('children-count-wrapper');
  const childCountDisplay = document.getElementById('child-count-display');
  const childMinusBtn = document.getElementById('child-minus-btn');
  const childPlusBtn = document.getElementById('child-plus-btn');

  // Attendance Toggle
  attendanceRadios.forEach(radio => {
    radio.addEventListener('change', e => {
      rsvpState.attendance = e.target.value;
      if (rsvpState.attendance === 'yes') {
        attendingFields.style.display = 'block';
        declineFields.style.display = 'none';
      } else {
        attendingFields.style.display = 'none';
        declineFields.style.display = 'block';
      }
    });
  });

  // Guest counter
  if (guestMinusBtn && guestPlusBtn && guestCountDisplay) {
    guestMinusBtn.addEventListener('click', () => {
      if (rsvpState.guestCount > 1) {
        rsvpState.guestCount--;
        guestCountDisplay.textContent = rsvpState.guestCount;
        rsvpState.guests = rsvpState.guests.slice(0, rsvpState.guestCount);
        renderGuestInputs();
      }
    });

    guestPlusBtn.addEventListener('click', () => {
      if (rsvpState.guestCount < 10) {
        rsvpState.guestCount++;
        guestCountDisplay.textContent = rsvpState.guestCount;
        while (rsvpState.guests.length < rsvpState.guestCount) {
          rsvpState.guests.push({ name: '', email: '', dietary: '' });
        }
        renderGuestInputs();
      }
    });
  }

  // Children Toggle
  childrenRadios.forEach(radio => {
    radio.addEventListener('change', e => {
      rsvpState.hasChildren = e.target.value;
      if (rsvpState.hasChildren === 'yes') {
        childrenCountWrapper.style.display = 'block';
        if (rsvpState.childrenCount === 0) {
          rsvpState.childrenCount = 1;
          rsvpState.children = [{ name: '', dietary: '' }];
          if (childCountDisplay) childCountDisplay.textContent = '1';
        }
      } else {
        childrenCountWrapper.style.display = 'none';
        rsvpState.childrenCount = 0;
        rsvpState.children = [];
      }
      renderChildrenInputs();
    });
  });

  // Children Counter
  if (childMinusBtn && childPlusBtn && childCountDisplay) {
    childMinusBtn.addEventListener('click', () => {
      if (rsvpState.childrenCount > 1) {
        rsvpState.childrenCount--;
        childCountDisplay.textContent = rsvpState.childrenCount;
        rsvpState.children = rsvpState.children.slice(0, rsvpState.childrenCount);
        renderChildrenInputs();
      }
    });

    childPlusBtn.addEventListener('click', () => {
      if (rsvpState.childrenCount < 6) {
        rsvpState.childrenCount++;
        childCountDisplay.textContent = rsvpState.childrenCount;
        while (rsvpState.children.length < rsvpState.childrenCount) {
          rsvpState.children.push({ name: '', dietary: '' });
        }
        renderChildrenInputs();
      }
    });
  }

  // Events selection checkboxes
  document.querySelectorAll('.event-checkbox').forEach(cb => {
    cb.addEventListener('change', () => {
      const selected = [];
      document.querySelectorAll('.event-checkbox:checked').forEach(c => {
        selected.push(c.value);
      });
      rsvpState.events = selected;
    });
  });

  // Message field
  const msgInput = document.getElementById('rsvp-message');
  if (msgInput) {
    msgInput.addEventListener('input', e => {
      rsvpState.message = e.target.value;
    });
  }

  // Decline name input
  const declineNameInput = document.getElementById('decline-name');
  if (declineNameInput) {
    declineNameInput.addEventListener('input', e => {
      rsvpState.guests[0] = rsvpState.guests[0] || { name: '', email: '', dietary: '' };
      rsvpState.guests[0].name = e.target.value;
    });
  }

  // Initial render
  renderGuestInputs();

  // Form Submit
  if (form) {
    form.addEventListener('submit', e => {
      e.preventDefault();
      handleRsvpSubmission();
    });
  }

  // Load existing RSVP if previously stored
  loadStoredRsvp();
}

function handleRsvpSubmission() {
  const submitBtn = document.getElementById('rsvp-submit-btn');
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.textContent = t('rsvp.sending');
  }

  // Persist locally
  const submissionData = {
    attendance: rsvpState.attendance,
    guestCount: rsvpState.attendance === 'yes' ? rsvpState.guestCount : 0,
    guests: rsvpState.guests,
    hasChildren: rsvpState.hasChildren,
    childrenCount: rsvpState.hasChildren === 'yes' ? rsvpState.childrenCount : 0,
    children: rsvpState.children,
    events: rsvpState.events,
    message: rsvpState.message,
    submittedAt: new Date().toISOString()
  };

  localStorage.setItem('maison_doree_rsvp', JSON.stringify(submissionData));

  setTimeout(() => {
    showConfirmationScreen(submissionData);
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = t('rsvp.send');
    }
  }, 600);
}

function showConfirmationScreen(data) {
  const rsvpFormSection = document.getElementById('rsvp-form-container');
  const confirmationSection = document.getElementById('rsvp-confirmation-container');
  const celebrationVideo = document.getElementById('rsvp-celebration-video');
  const calendarBtn = document.getElementById('add-calendar-btn');

  if (!rsvpFormSection || !confirmationSection) return;

  rsvpFormSection.style.display = 'none';
  confirmationSection.style.display = 'block';

  // If Yes, play celebration webm video
  if (data.attendance === 'yes') {
    document.getElementById('confirm-yes-block').style.display = 'block';
    document.getElementById('confirm-no-block').style.display = 'none';

    if (celebrationVideo) {
      celebrationVideo.currentTime = 0;
      celebrationVideo.play().catch(() => {});
    }

    // Setup Google Calendar button
    if (calendarBtn) {
      calendarBtn.onclick = () => {
        const title = encodeURIComponent('Wedding of Mohammed Ahmed Raza & Meena Nazneen');
        const details = encodeURIComponent('Nikah: Thursday, 22 October 2026 (After Asar Namaz) at Jamia Masjid, Fateh Darwaza | Valima Ceremony: Saturday, 24 October 2026 (Dinner: 8:30 PM) at Kingston Convention, Bahadurpura, Hyderabad');
        const location = encodeURIComponent('Kingston Convention, Opp. Sub Registration Office, Bahadurpura, Hyderabad');
        const url = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${title}&dates=20261022T110000Z/20261024T183000Z&location=${location}&details=${details}`;
        window.open(url, '_blank');
      };
    }
  } else {
    document.getElementById('confirm-yes-block').style.display = 'none';
    document.getElementById('confirm-no-block').style.display = 'block';
  }

  // Smooth scroll to confirmation
  confirmationSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function loadStoredRsvp() {
  const raw = localStorage.getItem('maison_doree_rsvp');
  if (!raw) return;

  try {
    const data = JSON.parse(raw);
    const changeBtn = document.getElementById('change-rsvp-btn');
    if (changeBtn) {
      changeBtn.onclick = () => {
        document.getElementById('rsvp-confirmation-container').style.display = 'none';
        document.getElementById('rsvp-form-container').style.display = 'block';
      };
    }
  } catch (e) {
    console.error('Error reading stored RSVP', e);
  }
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// ============================================================================
// Initialization on DOMContentLoaded
// ============================================================================
document.addEventListener('DOMContentLoaded', () => {
  // Apply language
  updatePageLanguage();

  // Audio Toggle button click handler
  const audioToggle = document.getElementById('audio-toggle');
  if (audioToggle) {
    audioToggle.addEventListener('click', toggleAudioMute);
  }

  // Initialize features
  setupIntroExperience();
  setupCurtainParallax();
  setupScrollReveal();
  setupRsvpForm();

  // Start countdown ticker
  updateCountdown();
  setInterval(updateCountdown, 1000);

  // Smooth scroll for hero 'keep scrolling' / discover button
  const scrollNextBtn = document.getElementById('scroll-to-next');
  if (scrollNextBtn) {
    scrollNextBtn.addEventListener('click', () => {
      const target = document.getElementById('quran-verse');
      if (target) target.scrollIntoView({ behavior: 'smooth' });
    });
  }

  const scrollDownBtn = document.getElementById('scroll-to-countdown');
  if (scrollDownBtn) {
    scrollDownBtn.addEventListener('click', () => {
      const target = document.getElementById('countdown');
      if (target) target.scrollIntoView({ behavior: 'smooth' });
    });
  }
});
